#include <Cellerator/compiler/diagnostics/expose_structured_diagnostic_and_query_apis_v1.hh>
#include <sstream>
namespace cellerator::compiler::diagnostics::v1 {namespace {std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='"'||c=='\\')o+='\\';o+=c;}return o;}}std::string to_lsp_json(const structured_diagnostic&d){std::ostringstream o;o<<"{\"id\":"<<d.stable_id<<",\"related\":"<<d.related_id<<",\"range\":{\"line\":"<<d.line<<",\"column\":"<<d.column<<"},\"severity\":"<<d.severity<<",\"code\":\""<<esc(d.code)<<"\",\"message\":\""<<esc(d.message)<<"\"}";return o.str();}std::size_t stream_diagnostics(const std::vector<structured_diagnostic>&ds,diagnostic_callback cb,void*ctx,cancellation_query cancel,void*cancel_ctx){if(!cb)return 0;std::size_t n=0;for(auto&d:ds){if(cancel&&cancel(cancel_ctx))break;if(!cb(d,ctx))break;++n;}return n;}}
